CREATE TABLE "better_supabase"."agent_mandates" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "session_id"      uuid,
  "vct"             text                     NOT NULL,
  "status"          text                     NOT NULL DEFAULT 'active'::text,
  "credential"      text                     NOT NULL,
  "credential_hash" text                     NOT NULL,
  "issuer_kid"      text,
  "subject"         text,
  "expires_at"      timestamp with time zone NOT NULL,
  "consumed_at"     timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agent_mandates_pkey" PRIMARY KEY (id),
  CONSTRAINT "agent_mandates_tenant_id_credential_hash_key" UNIQUE (tenant_id, credential_hash),
  CONSTRAINT "bsb_agent_mandates_check" CHECK (((status = 'consumed'::text) = (consumed_at IS NOT NULL))),
  CONSTRAINT "bsb_agent_mandates_credential_check" CHECK (((length(credential) >= 1) AND (length(credential) <= 16384))),
  CONSTRAINT "bsb_agent_mandates_credential_hash_check" CHECK (((length(credential_hash) >= 1) AND (length(credential_hash) <= 128))),
  CONSTRAINT "bsb_agent_mandates_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'consumed'::text, 'revoked'::text]))),
  CONSTRAINT "bsb_agent_mandates_vct_check" CHECK ((vct = ANY (ARRAY['mandate.checkout.open.1'::text, 'mandate.checkout.1'::text]))),
  "created_by"      uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."agent_mandates"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."checkout_sessions" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "cart_id"         uuid                     NOT NULL,
  "protocol"        text                     NOT NULL,
  "status"          text                     NOT NULL DEFAULT 'open'::text,
  "idempotency_key" text                     NOT NULL,
  "request_hash"    text                     NOT NULL,
  "buyer"           jsonb,
  "order_id"        uuid,
  "expires_at"      timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_checkout_sessions_check" CHECK (((status = 'completed'::text) = (order_id IS NOT NULL))),
  CONSTRAINT "bsb_checkout_sessions_idempotency_key_check" CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 255))),
  CONSTRAINT "bsb_checkout_sessions_protocol_check" CHECK ((protocol = ANY (ARRAY['acp'::text, 'ucp'::text]))),
  CONSTRAINT "bsb_checkout_sessions_request_hash_check" CHECK (((length(request_hash) >= 1) AND (length(request_hash) <= 128))),
  CONSTRAINT "bsb_checkout_sessions_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'ready'::text, 'completed'::text, 'canceled'::text]))),
  CONSTRAINT "checkout_sessions_pkey" PRIMARY KEY (id),
  CONSTRAINT "checkout_sessions_tenant_id_idempotency_key_key" UNIQUE (tenant_id, idempotency_key),
  "created_by"      uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."checkout_sessions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."collection_favorites" (
