);

ALTER TABLE "better_supabase"."collection_favorites"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."review_stats" (
  "tenant_id"    uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "subject_id"   text                     NOT NULL,
  "review_count" integer                  NOT NULL DEFAULT 0,
  "rating_total" bigint                   NOT NULL DEFAULT 0,
  "histogram"    jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "review_stats_pkey" PRIMARY KEY (tenant_id, subject_type, subject_id)
);

ALTER TABLE "better_supabase"."review_stats"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."reviews" (
  "id"               uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"        uuid                     NOT NULL,
  "subject_type"     text                     NOT NULL,
  "subject_id"       text                     NOT NULL,
  "author_id"        uuid,
  "author_name"      text,
  "rating"           smallint                 NOT NULL,
  "title"            text,
  "body"             text,
  "status"           text                     NOT NULL DEFAULT 'pending'::text,
  "verified"         boolean                  NOT NULL DEFAULT false,
  "rejection_reason" text,
  "reply"            text,
  "replied_by"       uuid,
  "replied_at"       timestamp with time zone,
  "published_at"     timestamp with time zone,
  "created_at"       timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_reviews_author_name_check" CHECK (((author_name IS NULL) OR (length(author_name) <= 100))),
  CONSTRAINT "bsb_reviews_body_check" CHECK (((body IS NULL) OR (length(body) <= 5000))),
  CONSTRAINT "bsb_reviews_rating_check" CHECK (((rating >= 1) AND (rating <= 5))),
  CONSTRAINT "bsb_reviews_rejection_reason_check" CHECK (((rejection_reason IS NULL) OR (length(rejection_reason) <= 1000))),
  CONSTRAINT "bsb_reviews_reply_check" CHECK (((reply IS NULL) OR (length(reply) <= 5000))),
  CONSTRAINT "bsb_reviews_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'published'::text, 'rejected'::text]))),
  CONSTRAINT "bsb_reviews_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "bsb_reviews_subject_type_check" CHECK ((subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text)),
  CONSTRAINT "bsb_reviews_title_check" CHECK (((title IS NULL) OR (length(title) <= 200))),
  CONSTRAINT "reviews_pkey" PRIMARY KEY (id),
  CONSTRAINT "reviews_tenant_id_subject_type_subject_id_author_id_key" UNIQUE (tenant_id, subject_type, subject_id, author_id)
);

ALTER TABLE "better_supabase"."reviews"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."saved_items" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_id"      uuid                     NOT NULL,
