CREATE TABLE "better_supabase"."subject_collections" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "scope"        text                     NOT NULL DEFAULT 'user'::text,
  "owner_id"     uuid,
  "team_id"      text,
  "name"         text                     NOT NULL,
  "description"  text,
  "archived_at"  timestamp with time zone,
  "created_by"   uuid,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_subject_collections_check1" CHECK (((scope <> 'team'::text) OR (team_id IS NOT NULL))),
  CONSTRAINT "bsb_subject_collections_check" CHECK (((scope <> 'user'::text) OR (owner_id IS NOT NULL))),
  CONSTRAINT "bsb_subject_collections_description_check" CHECK ((length(description) <= 2000)),
  CONSTRAINT "bsb_subject_collections_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 120))),
  CONSTRAINT "bsb_subject_collections_scope_check" CHECK ((scope = ANY (ARRAY['user'::text, 'team'::text, 'tenant'::text]))),
  CONSTRAINT "subject_collections_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."subject_collections"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."warranty_claims" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "title"        text                     NOT NULL,
  "supplier_id"  uuid,
  "manufacturer" text,
  "asset_id"     uuid                     NOT NULL,
  "amount"       bigint                   NOT NULL,
  "currency"     text                     NOT NULL,
  "status"       text                     NOT NULL DEFAULT 'draft'::text,
  "decision"     text,
  "decided_at"   timestamp with time zone,
  "decided_by"   uuid,
  "created_by"   uuid,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_warranty_claims_amount_check" CHECK ((amount >= 0)),
  CONSTRAINT "bsb_warranty_claims_check" CHECK (((supplier_id IS NOT NULL) OR (NULLIF(btrim(manufacturer), ''::text) IS NOT NULL))),
  CONSTRAINT "bsb_warranty_claims_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_warranty_claims_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'denied'::text, 'closed'::text]))),
  CONSTRAINT "bsb_warranty_claims_title_check" CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200))),
  CONSTRAINT "warranty_claims_pkey" PRIMARY KEY (id),
  CONSTRAINT "warranty_claims_tenant_id_id_key" UNIQUE (tenant_id, id)
);

ALTER TABLE "better_supabase"."warranty_claims"
  ENABLE ROW LEVEL SECURITY;

