      WHERE ((s.id = (deadlines.subject_id)::uuid) AND (s.tenant_id = deadlines.tenant_id)))) AND
        (tenant_id IN ( SELECT better_supabase.tenant_ids_with('compliance.read'::text) AS tenant_ids_with)))
